const toCents = (amount: string) => {
  const [whole, frac = ''] = amount.split('.');
  return Number(whole) * 100 + Number(frac.padEnd(2, '0'));
};

/** Only OPEN and SETTLED claims count toward claimed, due-total and every total. */
export const counts = (c: Claim) => c.status === 'OPEN' || c.status === 'SETTLED';

/** A claim's figure: the due fixed when it was settled, else the figure a statement bound it to, else
 *  its live due at `pct` (n/a without one). */
export const claimDue = (c: Claim, pct: string | undefined): string =>
  c.settledDue ?? (c.stated ? c.statedDue ?? NA : due(c.amount, pct));

/** Whether the claim keeps a figure of its own, whatever the rates: settled, or bound by a statement. */
export const hasFixedDue = (c: Claim) => c.settledDue !== null || (c.stated && c.statedDue !== null);

/** The counted claims' amounts added up, with two decimals. */
export function claimed(claims: Claim[]): string {
  const cents = claims.filter(counts).reduce((sum, c) => sum + toCents(c.amount), 0);
  return `${Math.floor(cents / 100)}.${String(cents % 100).padStart(2, '0')}`;
}

export function ClaimedTotal({ sheet }: { sheet: string }) {
  const claims = useClaims(sheet);
  return (
    <p>
      Claimed total: <strong data-testid="rollup-claimed-total">{claimed(claims)}</strong>
    </p>
  );
}

/** The claims cell of a person's row: the claim form and the person's claims, newest first, each
 *  with its due at the person's grade's rate in force on its date (`pctOn`, undefined when none is). */
export function PersonClaims({ sheet, personId, claims, pctOn }: {
  sheet: string; personId: number; claims: Claim[]; pctOn: (date: string) => string | undefined;
}) {
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, postJson } from '../../api/http';
import { useSingleSubmit } from '../../api/useSingleSubmit';
import { useCurrentUser } from '../session/SignIn';
import { claimDue, counts, useClaims } from '../claims/Claims';
import { usePeople } from '../people/People';
import { rateOn, total, useRates } from '../rates/Rates';
import { type Period, inPeriod, periodsKey, periodsPath, usePeriods } from './usePeriods';

// The sheet's periods, added here, each with its due-total: the figures of the claims that count
// whose date falls in it, each at its person's grade's rate in force on its date, skipping n/a.
// A closed period shows the due-total it was closed at instead, whatever rates do later.
export function Periods({ sheet }: { sheet: string }) {
  const periods = usePeriods(sheet);
  const people = usePeople(sheet);
  const claims = useClaims(sheet);
  const rates = useRates(sheet);
  const gradeOf = new Map(people.map((p) => [p.id, p.grade]));
  const dueTotalOf = (period: Period) =>
    total(claims
      .filter((c) => counts(c) && inPeriod(period, c.date) && gradeOf.has(c.personId))
      .map((c) => claimDue(c, rateOn(rates, gradeOf.get(c.personId)!, c.date))));

  return (
    <section>
      <h2>Periods</h2>
      <PeriodForm sheet={sheet} />
      <table>
        <thead>
          <tr>
            <th>Name</th>
            <th>From</th>
            <th>To</th>
            <th>Due total</th>
            <th>Closed</th>
            <th />
          </tr>
        </thead>
        <tbody>
          {periods.map((p) => (
            <PeriodRow key={p.name} sheet={sheet} period={p}
              dueTotal={p.closed && p.closedTotal != null ? p.closedTotal : dueTotalOf(p)} />
          ))}
        </tbody>
      </table>
    </section>
  );
}

